**Python:**

```python
def is_prime(n):
  """Checks if a number is prime."""
  if n <= 1:
    return False
  for i in range(2, int(n**0.5) + 1):
    if n % i == 0:
      return False
  return True

def find_primes(limit):
  """Finds prime numbers up to a given limit."""
  primes = []
  for num in range(2, limit + 1):
    if is_prime(num):
      primes.append(num)
  return primes

limit = 20
prime_numbers = find_primes(limit)
print(f"Prime numbers up to {limit}: {prime_numbers}")
```

**JavaScript:**

```javascript
function isPrime(n) {
  if (n <= 1) return false;
  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) return false;
  }
  return true;
}

function findPrimes(limit) {
  const primes = [];
  for (let i = 2; i <= limit; i++) {
    if (isPrime(i)) primes.push(i);
  }
  return primes;
}

const limit = 20;
const primeNumbers = findPrimes(limit);
console.log(`Prime numbers up to ${limit}:`, primeNumbers);
```

**C++:**

```c++
#include <iostream>
#include <vector>
#include <cmath>

bool isPrime(int n) {
  if (n <= 1) return false;
  for (int i = 2; i <= sqrt(n); ++i) {
    if (n % i == 0) return false;
  }
  return true;
}

std::vector<int> findPrimes(int limit) {
  std::vector<int> primes;
  for (int i = 2; i <= limit; ++i) {
    if (isPrime(i)) primes.push_back(i);
  }
  return primes;
}

int main() {
  int limit = 20;
  std::vector<int> primeNumbers = findPrimes(limit);
  std::cout << "Prime numbers up to " << limit << ": ";
  for (int prime : primeNumbers) {
    std::cout << prime << " ";
  }
  std::cout << std::endl;
  return 0;
}
```

These examples show how to identify prime numbers.  Remember to adjust the `limit` variable to change the range of numbers checked.  More efficient algorithms exist for finding larger prime numbers, but these examples are suitable for introductory purposes.
